package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__findDeserializer_TriageGen0Test {

    private DeserializationContext ctxt;
    private TypeIdResolver idResolver;
    private BeanProperty property;
    private JavaType baseType;
    private JavaType simpleType;
    private JsonDeserializer<Object> mockDeserializer;
    private TestTypeDeserializer testInstance;
    private Map<String, JsonDeserializer<Object>> deserializers;

    // Concrete implementation for testing protected method
    private static class TestTypeDeserializer extends TypeDeserializerBase {
        private final Map<String, JsonDeserializer<Object>> mockDeserializers = new HashMap<>();

        protected TestTypeDeserializer(JavaType baseType, TypeIdResolver idRes, String typePropertyName, 
                                     boolean typeIdVisible, JavaType defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        // Expose protected method for testing
        @Override
        public JsonDeserializer<Object> _findDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return super._findDeserializer(ctxt, typeId);
        }

        // Mock implementation of internal methods to control flow
        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return null; 
        }

        @Override
        protected JavaType _handleUnknownTypeId(DeserializationContext ctxt, String typeId, 
                                               TypeIdResolver idResolver, JavaType baseType) throws IOException {
            return null;
        }

        // Required abstract methods
        @Override public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() { return null; }
        @Override public String baseTypeName() { return "test"; }
        @Override public com.fasterxml.jackson.databind.jsontype.impl.TypeDeserializer forProperty(BeanProperty prop) { return null; }

        // Helper to inject deserializers map via reflection or manual override if possible
        // Since _deserializers is private in real Jackson, we simulate the behavior 
        // by overriding logic if needed, but here we rely on the actual class structure.
        // In this test, we will use a spy or a subclass that exposes the field.
    }

    // We need a way to access the private _deserializers field for the test
    private static class TestTypeDeserializerWithMap extends TestTypeDeserializer {
        public final Map<String, JsonDeserializer<Object>> _deserializers = new HashMap<>();

        public TestTypeDeserializerWithMap(JavaType baseType, TypeIdResolver idRes, String typePropertyName, 
                                         boolean typeIdVisible, JavaType defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        // We must override the method to use our local map because the original uses the private field
        // However, since the original method uses _deserializers directly, 
        // we use reflection in the test to populate the real field if we were using the real class.
        // For this unit test, we will use a Spy on the real class.
    }

    @Before
    public void setup() throws Exception {
        ctxt = mock(DeserializationContext.class);
        idResolver = mock(TypeIdResolver.class);
        property = mock(BeanProperty.class);
        baseType = mock(JavaType.class);
        simpleType = mock(JavaType.class);
        mockDeserializer = mock(JsonDeserializer.class);

        when(ctxt.getTypeFactory()).thenReturn(TypeFactory.defaultInstance());

        // Setup the instance using a spy to manipulate the private _deserializers map
        testInstance = spy(new TestTypeDeserializer(baseType, idResolver, "type", true, null));

        // Use reflection to inject a map into the private field _deserializers
        java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_deserializers");
        field.setAccessible(true);
        Map<String, JsonDeserializer<Object>> map = new HashMap<>();
        field.set(testInstance, map);
    }

    @Test
    public void testFindDeserializer_AlreadyExists() throws IOException {
        String typeId = "existing";
        java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_deserializers");
        field.setAccessible(true);
        ((Map<String, JsonDeserializer<Object>>) field.get(testInstance)).put(typeId, mockDeserializer);

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
        verifyNoInteractions(idResolver);
    }

    @Test
    public void testFindDeserializer_TypeIdFoundViaResolver() throws IOException {
        String typeId = "newType";
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(simpleType);
        when(ctxt.findContextualValueDeserializer(eq(simpleType), any())).thenReturn(mockDeserializer);

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
        verify(idResolver).typeFromId(ctxt, typeId);
    }

    @Test
    public void testFindDeserializer_DefaultImplFallback() throws IOException {
        String typeId = "unknown";
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);

        // Mock _findDefaultImplDeserializer via spy
        doReturn(mockDeserializer).when(testInstance)._findDefaultImplDeserializer(ctxt);

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
        verify(testInstance)._findDefaultImplDeserializer(ctxt);
    }

    @Test
    public void testFindDeserializer_HandleUnknownTypeIdFound() throws IOException {
        String typeId = "unknown";
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        doReturn(null).when(testInstance)._findDefaultImplDeserializer(ctxt);

        JavaType actualType = mock(JavaType.class);
        doReturn(actualType).when(testInstance)._handleUnknownTypeId(eq(ctxt), eq(typeId), eq(idResolver), eq(baseType));
        when(ctxt.findContextualValueDeserializer(actualType, property)).thenReturn(mockDeserializer);

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
    }

    @Test
    public void testFindDeserializer_HandleUnknownTypeIdReturnsNull() throws IOException {
        String typeId = "unknown";
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        doReturn(null).when(testInstance)._findDefaultImplDeserializer(ctxt);
        doReturn(null).when(testInstance)._handleUnknownTypeId(any(), anyString(), any(), any());

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertNull(result);
    }

    @Test
    public void testFindDeserializer_SpecializedTypeWithBaseTypeMatch() throws IOException {
        String typeId = "typeWithBaseMatch";
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(simpleType);

        // Mock same class check
        when(baseType.getClass()).thenReturn(simpleType.getClass());
        when(simpleType.getRawClass()).thenReturn(Object.class);

        JavaType specializedType = mock(JavaType.class);
        when(ctxt.getTypeFactory().constructSpecializedType(baseType, Object.class)).thenReturn(specializedType);
        when(ctxt.findContextualValueDeserializer(specializedType, property)).thenReturn(mockDeserializer);

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
    }

    @Test
    public void testFindDeserializer_NoSpecializationIfBaseTypeNull() throws IOException {
        String typeId = "typeNoBase";
        // Create new instance with null baseType via reflection or constructor
        TestTypeDeserializer noBaseInstance = spy(new TestTypeDeserializer(null, idResolver, "type", true, null));
        java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_deserializers");
        field.setAccessible(true);
        field.set(noBaseInstance, new HashMap<String, JsonDeserializer<Object>>());

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(simpleType);
        when(ctxt.findContextualValueDeserializer(simpleType, property)).thenReturn(mockDeserializer);

        JsonDeserializer<Object> result = noBaseInstance._findDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
    }

    @Test
    public void testFindDeserializer_NoSpecializationIfClassDifferent() throws IOException {
        String typeId = "typeDiffClass";
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(simpleType);

        // Different class
        when(baseType.getClass()).thenReturn(Object.class);
        when(simpleType.getClass()).thenReturn(String.class);

        when(ctxt.findContextualValueDeserializer(simpleType, property)).thenReturn(mockDeserializer);

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertEquals(mockDeserializer, result);
    }
}
